using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Web.Script.Serialization;using ReplierDesktop;
public static class GroundedBeforeAfter {
 public static int Main(string[] args){try{string root=args[0];var json=new JavaScriptSerializer{MaxJsonLength=16*1024*1024};var video=new Video{Id="CFYOk550ckc",Title="역대급 눈물겨운 120만원 배틀그라운드‘한정판 벤틀리 스킨’ㅋㅋ 이쁜데요?!",Channel="김블루"};var content=new ContentStore(Path.Combine(root,"extension/data/replier/content")).Load(video.Id);var evidence=CommentService.Evidence(content,video.Title).ToArray();
 string[] before={"스킨 디자인은 정말 역대급이네요. 다만 게임 플레이가 좀 더 긴장감 있었으면 좋았을 것 같아요.","벤틀리 스킨 진짜 예쁘네요. 근데 좀 더 내구성이 있었으면 좋겠어요."};
 var checkedBefore=new List<object>();foreach(string name in DualCommentService.Models)using(var m=new LocalModel(Path.Combine(root,"extension/.runtime/replier-llm"),name)){foreach(string text in before){var r=new WholeCommentGrounding(m).Assess(video,evidence,text,CancellationToken.None).GetAwaiter().GetResult();checkedBefore.Add(new{model=name,text=text,review=r});Console.WriteLine("BEFORE REVIEW "+name+" "+r.Supported+" "+r.Reason);}m.Unload().GetAwaiter().GetResult();}
 Console.WriteLine("START ONE fresh production generation");DualCommentResult result;using(var service=new DualCommentService(Path.Combine(root,"extension/.runtime/replier-llm"))){result=service.Generate(video,content,CancellationToken.None,true).GetAwaiter().GetResult();}
 var best=result.Batches.Where(b=>b.Result!=null).SelectMany(b=>b.Result.Comments).Where(c=>c.FitEligible==true).OrderByDescending(c=>c.FitScore).ThenByDescending(c=>c.TiePreference).FirstOrDefault();Console.WriteLine("AFTER "+(best==null?"NONE":best.Text)+" SCORE "+(best==null?"NONE":best.FitScore.ToString())+" ERROR "+result.ScoreError);foreach(var b in result.Batches){Console.WriteLine(b.Label+" "+b.Error);if(b.Result!=null)foreach(var c in b.Result.Comments)Console.WriteLine(c.FitScore+" | "+c.Text);}
 File.WriteAllText(Path.Combine(root,"extension/data/replier-grounded-checks/whole-comment-before-after-CFYOk550ckc.json"),json.Serialize(new{video=video,before=checkedBefore,after=result,best=best}));return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
